import dataclasses

def _types(cls):
    out = {}
    for f in dataclasses.fields(cls):
        out[f.name] = f.type if isinstance(f.type, str) else f.type.__name__
    return out

assert _types(Item) == {'name': 'str', 'price': 'float', 'quantity': 'int'}, _types(Item)
assert list(_types(Item)) == ['name', 'price', 'quantity'], 'keep the fields in the order name, price, quantity'

